// pages/logout.js
import React from "react";
import { useNavigate } from "react-router-dom";
import { logout } from "../services/api"; // Ensure the correct path to the API utility

const Logout = () => {
    const navigate = useNavigate();

    const handleLogout = async () => {
        try {
            const response = await logout(); // Call the API for logout
            console.log("Logout response:", response);

            // Clear the token from localStorage
            localStorage.removeItem("token");

            // Navigate to the login page
            navigate("/");
        } catch (error) {
            console.error("Logout failed:", error);
            // Optionally, handle logout failure
        }
    };

    React.useEffect(() => {
        handleLogout(); // Trigger logout on component mount
    }, []);

    return (
        <div>
            <h1>Logging out...</h1>
        </div>
    );
};

export default Logout;
